                .toList();
        List<Person> changed = new ArrayList<>();
        for (Person person : listed) {
            try {
                changed.add(service.retire(sheetId, user, person.getId(), from));
            } catch (PersonNotFoundException | ObjectOptimisticLockingFailureException e) {
                // Left as it is.
            }
        }
        return changed;
    }
}

